const prefix=`export HARNESS_SKILL_DIR='${load("skill")}'\n/opt/anaconda3/bin/python3 -I -B "$HARNESS_SKILL_DIR/scripts/harness.py" --task-home '${load("workspace")}/tasks'`;
store("prefix",prefix);
const out=await Promise.allSettled(["show","update","reconcile"].map(cmd=>tools.exec_command({cmd:`${prefix} ${cmd} --help`})));
out.forEach((v,i)=>text({command:["show","update","reconcile"][i],result:v}));
text(await tools.exec_command({cmd:`cat '${load("skill")}/examples/workflow-cases.md'`}));

const results=await Promise.allSettled([
 tools.exec_command({cmd:`${load("prefix")} show 337385e7-c334-4cf4-8e9c-79ba86503df6`}),
 tools.exec_command({cmd:`/opt/anaconda3/bin/python3 -I -B - <<'PY'
import json, hashlib
from pathlib import Path
w=Path('${load("workspace")}')
r=json.loads((w/'failed-run/receipt.json').read_text())
p=w/'checkpoint.designcraft'
h=hashlib.sha256()
with p.open('rb') as f:
    for block in iter(lambda:f.read(1048576),b''): h.update(block)
print(json.dumps({'runId':r.get('runId'),'savedProjectCheckpoint':r.get('savedProjectCheckpoint'),'actualFile':{'path':str(p),'sizeBytes':p.stat().st_size,'sha256':h.hexdigest()},'diagnosticAlreadyExists':(w/'harness-reconcile-after-restart.json').exists()},ensure_ascii=False,indent=2))
PY`})
]);
for(let i=0;i<results.length;i++){text({kind:i===0?"show":"independent_checkpoint_verification",result:results[i]});}
if(results[0].status==="fulfilled"&&results[0].value.exit_code===0)store("before",JSON.parse(results[0].value.output));
if(results[1].status==="fulfilled"&&results[1].value.exit_code===0)store("verification",JSON.parse(results[1].value.output));

