publicToolCalls.input:
const v=load("verification"), b=load("before");
if(v.savedProjectCheckpoint.path!==v.actualFile.path||v.savedProjectCheckpoint.bytes!==v.actualFile.sizeBytes||v.savedProjectCheckpoint.sha256!==v.actualFile.sha256||v.runId!==b.runId)throw Error("Checkpoint mismatch; update blocked");
const patch=JSON.stringify({checkpointRefs:[v.actualFile.path]});
const result=await tools.exec_command({cmd:`${load("prefix")} update 337385e7-c334-4cf4-8e9c-79ba86503df6 --expected-revision ${b.revision} --json '${patch}'`});
text(result);
if(result.exit_code===0)store("updated",JSON.parse(result.output));

if(!load("updated"))throw Error("Update not confirmed");
const w=load("workspace");
text(await tools.exec_command({cmd:`set -C\n${load("prefix")} reconcile 337385e7-c334-4cf4-8e9c-79ba86503df6 --recovery-report '${w}/source-recovery.json' --reopen-receipt '${w}/reopen-run/receipt.json' --reopen-plan '${w}/reopen-plan.json' --original-plan '${w}/original-plan.json' --saved-project '${w}/checkpoint.designcraft' > '${w}/harness-reconcile-after-restart.json'`}));

const res=await Promise.allSettled([
tools.exec_command({cmd:`cat '${load("workspace")}/harness-reconcile-after-restart.json'`,max_output_tokens:14000}),
tools.exec_command({cmd:`${load("prefix")} show 337385e7-c334-4cf4-8e9c-79ba86503df6`})
]);
for(let i=0;i<res.length;i++){text({kind:i===0?"reconcile_diagnostic":"final_show",result:res[i]});}
if(res[0].status==="fulfilled"&&res[0].value.exit_code===0)store("diagnostic",JSON.parse(res[0].value.output));
if(res[1].status==="fulfilled"&&res[1].value.exit_code===0){
const after=JSON.parse(res[1].value.output);
store("final",after);
text({changedShowFields:Object.keys(after).filter(k=>JSON.stringify(after[k])!==JSON.stringify(load("before")[k])),reconcilePreservedTask:JSON.stringify(after)===JSON.stringify(load("updated"))});
}

